SELECT d.id, 'en', 'Archiving', '[["Period and basis","Six years under Fiscalisation Act art. 35, from the end of the year — and the e-invoice must be kept in its ORIGINAL form, so a PDF rendering of an XML invoice does not discharge it."],["Signature","Conditional. Required in some circumstances only — check which apply to you before deciding how to store."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 4;
