INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Aufbewahrung', '[["Frist und Grundlage","Sechs Jahre nach Art. 35 des Fiskalisierungsgesetzes, ab Jahresende — und die E-Rechnung ist in ihrer URSPRÜNGLICHEN Form aufzubewahren; ein PDF-Abbild einer XML-Rechnung genügt nicht."],["Signatur","Bedingt. Nur unter bestimmten Umständen erforderlich — prüfen Sie, welche auf Sie zutreffen, bevor Sie die Ablage festlegen."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 4;
