SELECT d.id, 'fr', 'Conservation', '[["Durée et fondement","Six ans selon l''art. 35 de la loi de fiscalisation, depuis la fin de l''année — et la facture électronique doit être conservée dans sa forme D''ORIGINE : un PDF d''une facture XML ne suffit pas."],["Signature","Conditionnelle. Exigée dans certains cas seulement — vérifiez lesquels vous concernent avant de choisir votre stockage."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 4;

